import ezdxf

def dump_texts_and_lines(path):
    print(f'=================== {path} ===================')
    doc = ezdxf.readfile(path)
    msp = doc.modelspace()
    for layer in sorted(list(set(e.dxf.layer for e in msp))):
        entities = [e for e in msp if e.dxf.layer == layer]
        print(f'--- Layer {layer}: {len(entities)} entities ---')
        for e in entities:
            if e.dxftype() == 'TEXT':
                print(f'  TEXT: \"{e.dxf.text}\" at ({e.dxf.insert.x:.2f}, {e.dxf.insert.y:.2f})')
            elif e.dxftype() == 'LWPOLYLINE':
                pts = e.get_points()
                if len(pts) <= 6:
                    print(f'  LWPOLY: closed={e.closed}, pts={pts}')
            elif e.dxftype() == 'LINE' and layer in ['OPENING', 'PANEL', 'JOINT', 'DECK', 'WALL']:
                print(f'  LINE: ({e.dxf.start.x:.2f}, {e.dxf.start.y:.2f}) to ({e.dxf.end.x:.2f}, {e.dxf.end.y:.2f})')

